async periods(f: DreScopeDto, actor: ProjectActorContext) {
    const periods = await this.ds.manager.find(DrePeriod, {
      where: { organizationId: this.org(actor, f.organization_id) },
      order: { month: 'DESC' },
      take: 1000,
    });
