      expenseDate: this.requiredDate(dto.expense_date, 'expense_date'),
      amount: dto.amount,
      status: ExpenseStatus.PENDING,
      approvedById: null,
      approvedAt: null,
      rejectedById: null,
      rejectedAt: null,
      paidById: null,
      paidAt: null,
      createdById: actor.id,
      updatedById: actor.id,
      metadata: dto.metadata ?? null,
      createdAt: now,
      updatedAt: now,
      deletedAt: null,
